import {explorationExample} from './career-exploration-ui.js';
import {expandedPayPanel} from './expanded-pay-ui.js';
import {expandedOccupationById} from './expanded-occupation-data.js';
import {expandedQuestionBank} from './expanded-question-bank.js';
import {expandedInterestStatus} from './expanded-interest.js';
import {escapeHTML as h} from './html.js';
export function expandedCheckPage(s,id){const o=expandedOccupationById(id),b=expandedQuestionBank[id];if(!o)return '<a href="#/degree-careers">Browse degree careers →</a>';const c=expandedInterestStatus(s,id);return `<section class="degree-inventory"><a href="#/degree-careers">← Explore degree careers</a><p class="eyebrow">EXPLORE YOUR INTERESTS</p><h1>Start with a small example.</h1><p>Notice what you would want to explore before focusing on a job title. You do not need prior professional experience. You can open the profession and its preparation whenever you want.</p><details class="guide-input-panel"><summary>See the profession behind these examples</summary><h2>${h(o.title)}</h2><h3>Understand the work</h3><p>${h(o.summary)}</p><ul>${o.tasks.map(t=>`<li>${h(t.text)}</li>`).join('')}</ul><p><strong>Preparation:</strong> ${h(o.preparation.typicalEducation[0])}. ${o.requiresExperience?'Related work is typically required before this destination role.':''}</p><a href="${h(o.url)}" target="_blank" rel="noopener noreferrer">Full official occupational profile ↗</a></details>${!b?.topEligible?'<p>Specific evidence is not sufficient to offer this category as a Top match. Keep browsing related occupations.</p>':`<h2>Reflect on three distinct interests</h2><p>Answer for what you would like to learn. Unfamiliarity is different from disliking the work. These editorial reflections do not measure aptitude.</p>${c.questions.map(q=>`<section class="guide-input-panel">${explorationExample(q.id)}<p><strong>${h(q.prompt)}</strong></p><div class="degree-options">${[['yes','Yes, I would like to learn'],['no','This does not interest me'],['unsure','I’m not sure'],['unfamiliar','I need a clearer example']].map(([value,label])=>`<button class="button secondary" data-action="expanded-interest-answer" data-id="${h(id)}" data-question="${h(q.id)}" data-value="${value}" aria-pressed="${q.answer?.response===value}">${label}</button>`).join('')}</div>${q.answer?.source==='profile-inferred'?`<p class="small">Simulated response: ${h(q.answer.response)} · ${h(q.answer.confidence)} confidence</p><p>${h(q.answer.evidence)}</p>${q.answer.reviewHold?`<p><strong>Evidence review:</strong> ${h(q.answer.reviewHold)}</p>`:''}`:''}</section>`).join('')}<p role="status"><strong>${h(c.headline)}.</strong> ${h(c.detail)}</p>`}<a class="button" href="#/journey/expanded-matches">Review current matches →</a></section>`;}
export function expandedCareerPanel(s,row,{choose=true}={}){const o=row.o,c=expandedInterestStatus(s,o.id);return `<section class="result-career-content"><p><strong>${o.educationGroup==='graduate'?'Graduate / professional degree':'College · bachelor’s degree'}</strong></p><p>${h(o.summary)}</p><section class="match-reasons"><h3>${c.confirmed?'Why this matches your interests':'Interests to clarify'}</h3><p>${c.confirmed?'Three distinct interests and your six-score interest profile support this career.':h(c.headline)}</p><ul>${c.questions.filter(q=>q.answer?.response==='yes').map(q=>`<li>${h(q.prompt)}${q.answer.source==='profile-inferred'?`<p>${h(q.answer.evidence)}</p>${q.answer.reviewHold?`<p><strong>Evidence review:</strong> ${h(q.answer.reviewHold)}</p>`:''}`:''}</li>`).join('')}</ul><p>${h(c.detail)}</p>${c.scopeReview?`<aside><strong>Explore the scope</strong><p>${h(c.scopeReview.resolvingQuestion)}</p><p>${h(c.scopeReview.issue)}</p></aside>`:''}<a href="#/journey/degree-check/${h(o.id)}">Review or clarify these interests →</a></section><section class="match-training"><h3>How to get there</h3><p>${h(o.preparation.typicalEducation[0])}</p>${o.requiresExperience?`<p>Related work is typically required: ${h(o.experience)}. This is a destination to prepare for, not an immediate entry job.</p>`:''}<p>${o.preparation.mapping.includes('broader')?'This education reference covers a broader occupation group; preparation for this specialty can differ.':'The education reference is matched to this occupation.'} Verify the exact program, supervised preparation and licensing for this role.</p><a href="${h(o.preparation.sourceURL)}" target="_blank" rel="noopener noreferrer">Preparation source ↗</a></section>${expandedPayPanel(s,o)}<a href="${h(o.url)}" target="_blank" rel="noopener noreferrer">Explore the official work profile ↗</a>${choose?`<p><button class="button" data-action="journey-plan" data-id="${h(o.id)}">Choose this career to explore →</button></p>`:''}</section>`;}
export function expandedPersonalPlan(s){const o=expandedOccupationById(s.guide.primaryCareer);if(!o)return '';return `<section class="results-plan"><h1>My plan · ${h(o.title)}</h1><p>This plan preserves your interest choice and next steps. Preparation, costs and first-paid-stage pay still need verification.</p>${expandedCareerPanel(s,{o},{choose:false})}<h2>My next steps</h2>${s.actions.filter(a=>a.careerId===o.id).map(a=>`<article class="personal-action"><label><input type="checkbox" data-action-check="${h(a.id)}" ${a.done?'checked':''}>${h(a.title)}</label><p>${h(a.detail)}</p><label>My notes<textarea data-plan-action="${h(a.id)}" data-plan-field="notice">${h(a.notice||'')}</textarea></label></article>`).join('')}<a href="#/journey/expanded-matches">Compare other matches →</a></section>`;}
